// script.js
const circle = document.getElementById('circle');
const marker = document.getElementById('marker');
const output = document.getElementById('output');

let radius = 0;

function updateMarkerPosition(event) {
    const rect = circle.getBoundingClientRect();
    const centerX = rect.left + rect.width / 2;
    const centerY = rect.top + rect.height / 2;

    const mouseX = event.clientX;
    const mouseY = event.clientY;

    const angle = Math.atan2(mouseY - centerY, mouseX - centerX);
    radius = Math.min(rect.width / 2, Math.max(0, Math.sqrt((mouseX - centerX) ** 2 + (mouseY - centerY) ** 2)));

    const markerX = centerX + radius * Math.cos(angle);
    const markerY = centerY + radius * Math.sin(angle);

    marker.style.left = `${markerX}px`;
    marker.style.top = `${markerY}px`;

    output.textContent = `Radius: ${Math.round(radius)}`;
}

circle.addEventListener('mousemove', updateMarkerPosition);
circle.addEventListener('click', updateMarkerPosition);
```

