### OCaml Example Code

This example will include the compute shader source code as a string and show how to call it from OCaml. It will compute the dot product of two vectors.

```ocaml
(* Required libraries, ensure you have the necessary OpenGL bindings *)
#require "gl";;

open Gl
open Glu
open Glut

(* Shader source code for the compute shader *)
let compute_shader_source = "
#version 430
layout(local_size_x = 1) in;
layout(std430, binding = 0) buffer InputA {
    float a[];
};
layout(std430, binding = 1) buffer InputB {
    float b[];
};
layout(std430, binding = 2) buffer Output {
    float result;
};

void main() {
    uint index = gl_GlobalInvocationID.x;
    result += a[index] * b[index];
}
"

(* Function to compile a shader *)
let compile_shader shader_type source =
  let shader = glCreateShader shader_type in
  glShaderSource shader 1 (ref source) null;
  glCompileShader shader;
  let status = glGetShaderiv shader GL_COMPILE_STATUS in
  if status = GL_FALSE then
    let info_log_length = glGetShaderiv shader GL_INFO_LOG_LENGTH in
    let info_log = Gl.get_shader_info_log shader info_log_length in
    failwith ("Shader compilation failed: " ^ info_log);
  shader

(* Function to create the compute program *)
let create_compute_program () =
  let program = glCreateProgram () in
  let compute_shader = compile_shader GL_COMPUTE_SHADER compute_shader_source in
  glAttachShader program compute_shader;
  glLinkProgram program;
  glDeleteShader compute_shader; (* Delete the shader after linking *)
  program

(* Dummy data for two vectors to compute dot product *)
let a_data = [| 1.0; 2.0; 3.0 |]
let b_data = [| 4.0; 5.0; 6.0 |]

let () =
  (* Initialize GLUT and create a window *)
  let _ = glutInit Sys.argv in
  glutInitDisplayMode GLUT_DOUBLE;
  glutInitWindowSize 800 600;
  glutCreateWindow "Compute Shader Dot Product";

  (* Initialize OpenGL *)
  glClearColor 0.0 0.0 0.0 1.0;
  let program = create_compute_program () in

  (* Create buffers for input and output *)
  let a_buffer = GlGenBuffers.create () in
  let b_buffer = GlGenBuffers.create () in
  let result_buffer = GlGenBuffers.create () in

  (* Bind and fill the input buffers *)
  glBindBuffer GL_SHADER_STORAGE_BUFFER a_buffer;
  glBufferData GL_SHADER_STORAGE_BUFFER (Array.length a_data * 4) (Bigarray.array1_of_genarray (Bigarray.Genarray.of_array Bigarray.Float32 Bigarray.c_layout a_data)) GL_STATIC_DRAW;

  glBindBuffer GL_SHADER_STORAGE_BUFFER b_buffer;
  glBufferData GL_SHADER_STORAGE_BUFFER (Array.length b_data * 4) (Bigarray.array1_of_genarray (Bigarray.Genarray.of_array Bigarray.Float32 Bigarray.c_layout b_data)) GL_STATIC_DRAW;

  (* Bind and create the output buffer *)
  glBindBuffer GL_SHADER_STORAGE_BUFFER result_buffer;
  glBufferData GL_SHADER_STORAGE_BUFFER 4 (Bigarray.array1_of_genarray (Bigarray.Genarray.create Bigarray.Float32 Bigarray.c_layout [| 0.0 |])) GL_DYNAMIC_DRAW;

  glBindBufferBase GL_SHADER_STORAGE_BUFFER 0 a_buffer;
  glBindBufferBase GL_SHADER_STORAGE_BUFFER 1 b_buffer;
  glBindBufferBase GL_SHADER_STORAGE_BUFFER 2 result_buffer;

  (* Dispatch the compute shader *)
  glUseProgram program;
  glDispatchCompute (Array.length a_data) 1 1;
  glMemoryBarrier GL_SHADER_STORAGE_BARRIER_BIT;

  (* Read back the result *)
  glBindBuffer GL_SHADER_STORAGE_BUFFER result_buffer;
  let results = Bigarray.array1_of_genarray (Bigarray.Genarray.create Bigarray.Float32 Bigarray.c_layout [| 0.0 |]) in
  glGetBufferSubData GL_SHADER_STORAGE_BUFFER 0 (Bigarray.Array1.dim results * 4) (Bigarray.Array1.start results);

  (* Print the result *)
  Printf.printf "Dot product: %f\n" (Bigarray.Array1.get results 0);

  (* Cleanup *)
  glDeleteBuffers 1 (ref a_buffer);
  glDeleteBuffers 1 (ref b_buffer);
  glDeleteBuffers 1 (ref result_buffer);
  glDeleteProgram program;

  (* Start the GLUT main loop *)
  glutMainLoop ()
```

### Explanation:
1. **Shader Code**: The compute shader takes two input buffers (`InputA` and `InputB`) and computes the dot product, storing the result in an output buffer (`Output`).

2. **Shader Compilation**: The code includes a function to compile the shader and link it into a program.

3. **Creating Buffers**: Buffers are created for the input vectors and the output result. Data is filled into the input buffers.

4. **Dispatching the Compute Shader**: The compute shader is executed using `glDispatchCompute`, which launches the shader with the number of elements to compute.

5. **Reading Results**: After dispatching, the result is read back from the output buffer.

6. **Cleanup**: Buffers and the shader program are cleaned up after use.

### Notes:
- You need to install the appropriate OpenGL and OCaml bindings.
- Make sure to link against the necessary libraries when compiling your OCaml code.
- This example is quite minimal and does not handle errors or OpenGL context creation in detail. Adjust it according to your needs, especially regarding OpenGL context setup and error checking.

Certainly! Below is an example of a simple GLSL implementation of old-school raycasting using a vertex shader and a fragment shader. This example assumes a 2D grid-based world where walls can be represented and raycasting is used to simulate a simple 3D perspective.

### Vertex Shader (raycast_vertex_shader.glsl)

The vertex shader simply passes through the vertex positions and texture coordinates.

```glsl
#version 330 core

layout(location = 0) in vec2 aPos; // Vertex position
layout(location = 1) in vec2 aTexCoord; // Texture coordinates

out vec2 TexCoord; // Output texture coordinates

void main() {
    gl_Position = vec4(aPos, 0.0, 1.0); // Transform the 2D vertex to clip space
    TexCoord = aTexCoord; // Pass through texture coordinates
}
```

### Fragment Shader (raycast_fragment_shader.glsl)

The fragment shader performs raycasting in the pixel shader, simulating a simple 3D perspective projection using a predefined grid.

```glsl
#version 330 core

in vec2 TexCoord; // Incoming texture coordinates

out vec4 FragColor; // Output color

uniform vec2 u_resolution; // Resolution of the screen
uniform vec2 u_playerPos; // Player position in the grid
uniform vec2 u_playerDir; // Direction the player is facing
uniform float u_fov; // Field of view
uniform int u_mapWidth; // Width of the map
uniform int u_mapHeight; // Height of the map
uniform int u_map[64]; // The grid map, make sure to set this up in your application

void main() {
    // Normalize pixel coordinates to the range [-1, 1]
    vec2 uv = gl_FragCoord.xy / u_resolution * 2.0 - 1.0;
    uv.x *= u_resolution.x / u_resolution.y; // Maintain aspect ratio

    // Calculate the ray direction
    float angle = atan(uv.x / (tan(u_fov / 2.0)));
    vec2 rayDir = normalize(vec2(cos(angle), sin(angle)));

    // Raycasting
    vec2 rayPos = u_playerPos;
    vec2 rayStep = rayDir;

    // For simplicity, we are using a fixed step size
    float stepSize = 0.1;
    float distance = 0.0;

    // Infinite loop to cast the ray
    while (distance < 100.0) {
        // Check if we hit a wall
        int mapX = int(rayPos.x);
        int mapY = int(rayPos.y);

        if (mapX >= 0 && mapX < u_mapWidth && mapY >= 0 && mapY < u_mapHeight) {
            if (u_map[mapY * u_mapWidth + mapX] > 0) { // Assuming 1 is a wall
                // Calculate distance to wall hit
                distance = length(rayPos - u_playerPos);
                break;
            }
        }

        // Move ray position forward
        rayPos += rayStep * stepSize;
    }

    // Simple shading based on distance (optional)
    float shade = 1.0 / (distance + 0.1); // Avoid division by zero
    FragColor = vec4(vec3(shade), 1.0); // Output color
}
```

### Explanation

1. **Vertex Shader**: This shader takes in vertex positions and texture coordinates and outputs them directly to the fragment shader.

2. **Fragment Shader**: 
   - It calculates the ray direction based on the pixel coordinates and the player's field of view.
   - It performs raycasting by stepping through the grid until it hits a wall or exceeds a maximum distance.
   - When a wall is hit, it computes the distance to the wall and applies a simple shading effect based on that distance.

### Usage

- You will need to set up the uniform variables (`u_resolution`, `u_playerPos`, `u_playerDir`, `u_fov`, `u_mapWidth`, `u_mapHeight`, `u_map`) in your application code before rendering.
- The `u_map` should be a flat array representing the 2D map where non-zero values represent walls.

This implementation is quite basic and can be expanded significantly for more complex behavior, textures, and dynamic elements.

