### FavoritesManager Class

```php
namespace App\Favorites;

use App\Models\User;
use App\Models\Favorite;
use Illuminate\Support\Facades\Session;

class FavoritesManager
{
    public function addFavorite($nameId, $user = null)
    {
        if ($user) {
            // If the user is logged in, save to the database
            return Favorite::create([
                'user_id' => $user->id,
                'name_id' => $nameId,
            ]);
        } else {
            // If the user is a guest, save to the session
            $favorites = Session::get('favorites', []);
            if (!in_array($nameId, $favorites)) {
                $favorites[] = $nameId;
                Session::put('favorites', $favorites);
            }
            return true;
        }
    }

    public function removeFavorite($nameId, $user = null)
    {
        if ($user) {
            // If the user is logged in, remove from the database
            return Favorite::where('user_id', $user->id)->where('name_id', $nameId)->delete();
        } else {
            // If the user is a guest, remove from the session
            $favorites = Session::get('favorites', []);
            if (($key = array_search($nameId, $favorites)) !== false) {
                unset($favorites[$key]);
                Session::put('favorites', array_values($favorites)); // Reindex the array
            }
            return true;
        }
    }

    public function getFavorites($user = null)
    {
        if ($user) {
            // If the user is logged in, retrieve from the database
            return Favorite::where('user_id', $user->id)->pluck('name_id')->toArray();
        } else {
            // If the user is a guest, retrieve from the session
            return Session::get('favorites', []);
        }
    }
}
```

