```php
namespace App\Http\Controllers;

use App\Favorites\FavoritesManager;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;

class FavoritesController extends Controller
{
    protected $favoritesManager;

    public function __construct(FavoritesManager $favoritesManager)
    {
        $this->favoritesManager = $favoritesManager;
    }

    public function add(Request $request)
    {
        $request->validate([
            'name_id' => 'required|integer|exists:names,id',
        ]);

        $user = Auth::user();
        $this->favoritesManager->addFavorite($request->name_id, $user);

        return response()->json(['message' => 'Favorite added successfully.']);
    }

    public function remove(Request $request)
    {
        $request->validate([
            'name_id' => 'required|integer|exists:names,id',
        ]);

        $user = Auth::user();
        $this->favoritesManager->removeFavorite($request->name_id, $user);

        return response()->json(['message' => 'Favorite removed successfully.']);
    }

    public function index()
    {
        $user = Auth::user();
        $favorites = $this->favoritesManager->getFavorites($user);

        return response()->json($favorites);
    }
}
