Here's a simple implementation of a Connect Four game in Python that you can run in your terminal. This version allows two players to take turns dropping their pieces into a 7x6 grid. The game checks for a winner after each move.

```python
# Connect Four Game

ROWS = 6
COLS = 7
EMPTY = " "
PLAYER1 = "X"
PLAYER2 = "O"

def create_board():
    return [[EMPTY for _ in range(COLS)] for _ in range(ROWS)]

def print_board(board):
    for row in board:
        print("|".join(row))
        print("-" * (COLS * 2 - 1))

def drop_piece(board, col, piece):
    for row in reversed(board):
        if row[col] == EMPTY:
            row[col] = piece
            return True
    return False

def is_winner(board, piece):
    # Check horizontal locations for win
    for c in range(COLS - 3):
        for r in range(ROWS):
            if all(board[r][c + i] == piece for i in range(4)):
                return True

    # Check vertical locations for win
    for c in range(COLS):
        for r in range(ROWS - 3):
            if all(board[r + i][c] == piece for i in range(4)):
                return True

    # Check positively sloped diagonals
    for c in range(COLS - 3):
        for r in range(ROWS - 3):
            if all(board[r + i][c + i] == piece for i in range(4)):
                return True

    # Check negatively sloped diagonals
    for c in range(COLS - 3):
        for r in range(3, ROWS):
            if all(board[r - i][c + i] == piece for i in range(4)):
                return True

    return False

def is_full(board):
    return all(board[0][c] != EMPTY for c in range(COLS))

def main():
    board = create_board()
    game_over = False
    turn = 0

    while not game_over:
        print_board(board)

        col = int(input(f"Player {turn % 2 + 1}, choose a column (0-{COLS - 1}): "))

        if col < 0 or col >= COLS:
            print("Invalid column. Try again.")
            continue

        if not drop_piece(board, col, PLAYER1 if turn % 2 == 0 else PLAYER2):
            print("Column full. Try again.")
            continue

        if is_winner(board, PLAYER1 if turn % 2 == 0 else PLAYER2):
            print_board(board)
            print(f"Player {turn % 2 + 1} wins!")
            game_over = True

        if is_full(board):
            print_board(board)
            print("It's a tie!")
            break

        turn += 1

if __name__ == "__main__":
    main()
```

### Instructions to Run the Game
1. Make sure you have Python installed on your machine.
2. Copy the code into a file named `connect_four.py`.
3. Open your terminal and navigate to the directory where the file is saved.
4. Run the game using the command: `python connect_four.py`.
5. Follow the prompts to play the game!

### Game Rules
- Players take turns to drop their pieces into one of the seven columns (0-6).
- The first player to connect four of their pieces (horizontally, vertically, or diagonally) wins the game.
- If the board fills up without a winner, the game ends in a tie.

Feel free to modify the game to add features such as better input handling, AI for single-player mode, or a graphical interface! Enjoy playing!

